from pathlib import Path

ROOT = Path('/app') if Path('/app/scenario.json').exists() else Path(__file__).resolve().parents[1]
CONFIG_PATH = Path('/app/scenario.json') if Path('/app/scenario.json').exists() else ROOT / 'data/input.json'
CONFIG = json.loads(CONFIG_PATH.read_text())
INPUT = json.loads((ROOT / 'data/workload.json').read_text())
PARSER = argparse.ArgumentParser()
PARSER.add_argument('--stage', required=True, choices=CONFIG['stages'])
PARSER.add_argument('--output', default=str(ROOT / 'outputs'))
ARGS = PARSER.parse_args()
OUT = Path(ARGS.output)
OUT.mkdir(parents=True, exist_ok=True)
STAGE = ARGS.stage


def read_stage(name):
    record = json.loads((OUT / f'stage-{name}.json').read_text())
    if record['status'] != 'success' or record['stage'] != name:
        raise ValueError(f'invalid upstream stage: {name}')
    return record['result']


def previous():
    parents = CONFIG['dependencies'][STAGE]
    if len(parents) != 1:
        raise ValueError(f'{STAGE} requires an explicit parent selection')
    return read_stage(parents[0])


def write_json(name, value):
    (OUT / name).write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')
    return value


def write_pickle(name, value):
    (OUT / name).write_bytes(pickle.dumps(value, protocol=4))


def write_csv(name, rows):
    with (OUT / name).open('w', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def report(name, title, value):
    (OUT / name).write_text('<!doctype html><meta charset="utf-8"><title>' + html.escape(title) + '</title><h1>' + html.escape(title) + '</h1><pre>' + html.escape(json.dumps(value, indent=2)) + '</pre>\n')


def regression(rows):
    xs = [row[0] for row in rows]
    ys = [row[1] for row in rows]
    mean_x, mean_y = statistics.mean(xs), statistics.mean(ys)
    denominator = sum((x - mean_x) ** 2 for x in xs)
    if denominator <= 0:
        raise ValueError('training inputs have zero variance')
    weight = sum((x - mean_x) * (y - mean_y) for x, y in rows) / denominator
    return {'weight': weight, 'bias': mean_y - weight * mean_x}


def predict(model, x):
    return model['weight'] * x + model['bias']


def rmse(model, rows):
    return math.sqrt(statistics.mean((predict(model, x) - y) ** 2 for x, y in rows))


def require(condition, message):
    if not condition:
        raise ValueError(message)


def run_stage():
    started = time.time_ns()
    parents = CONFIG['dependencies'][STAGE]
    for parent in parents:
        read_stage(parent)
    result = compute()
    require(isinstance(result, dict) and result, 'activity produced no domain result')
    record = {
        'showcase': CONFIG['slug'], 'stage': STAGE, 'status': 'success',
        'validationMode': 'local-workload', 'startedAtUnixNs': started,
        'finishedAtUnixNs': time.time_ns(),
        'inputDigest': hashlib.sha256(json.dumps(INPUT, sort_keys=True).encode()).hexdigest(),
        'dependencies': parents, 'result': result,
    }
    write_json(f'stage-{STAGE}.json', record)
    print(json.dumps({'activity': STAGE, 'status': 'success', 'resultKeys': list(result)}))

def dataset(rows=None):
    rows = INPUT['rows'] if rows is None else rows
    require(len(rows) >= 8 and all(len(row) == 2 and all(math.isfinite(v) for v in row) for row in rows), 'invalid regression dataset')
    return {'training': rows[::2], 'validation': rows[1::2]}


def mlflow_training():
    if STAGE == 'ingest-data':
        return {'rows': INPUT['rows'], 'source': 'versioned local regression measurements'}
    if STAGE == 'validate':
        split = dataset(previous()['rows'])
        require(len(split['validation']) > 2, 'insufficient held-out data')
        return split
    if STAGE == 'train':
        split = previous()
        model = regression(split['training'])
        write_pickle('model.pkl', model)
        return {**split, 'model': model}
    if STAGE == 'evaluate':
        result = previous()
        metrics = {'rmse': rmse(result['model'], result['validation']), 'heldOutSamples': len(result['validation'])}
        require(metrics['rmse'] < INPUT['maxRmse'], 'trained model failed held-out evaluation')
        write_json('metrics.json', metrics)
        report('report.html', 'Held-out regression evaluation', metrics)
        return {**result, 'metrics': metrics}
    if STAGE == 'register-model':
        result = previous()
        digest = hashlib.sha256((OUT / 'model.pkl').read_bytes()).hexdigest()
        entry = {'model': 'local-linear-regression', 'version': digest, 'artifact': 'model.pkl', 'metrics': result['metrics']}
        write_json('registry.json', entry)
        return entry
    if STAGE == 'log-mlflow-run':
        os.environ.setdefault('MLFLOW_DISABLE_AGENT_HINT', '1')
        import mlflow
        # Explicit local tracking store: the smoke run never sends data to a remote service.
        tracking = 'sqlite:///' + str((OUT / 'mlflow.db').resolve())
        mlflow.set_tracking_uri(tracking)
        experiment_id = mlflow.create_experiment('akoflow-local-training', artifact_location=(OUT / 'mlflow-artifacts').resolve().as_uri())
        mlflow.set_experiment(experiment_id=experiment_id)
        result = previous()
        with mlflow.start_run(run_name='cpu-smoke') as run:
            mlflow.log_params({'algorithm': 'ordinary-least-squares', 'training_samples': len(result['training'])})
            mlflow.log_metrics({'rmse': result['metrics']['rmse']})
            mlflow.log_artifact(str(OUT / 'model.pkl'))
            run_id = run.info.run_id
        observed = mlflow.tracking.MlflowClient().get_run(run_id)
        require(abs(observed.data.metrics['rmse'] - result['metrics']['rmse']) < 1e-12, 'MLflow did not persist the metric')
        metadata = {'runId': run_id, 'trackingStore': 'mlflow.db', 'status': observed.info.status, 'metrics': observed.data.metrics}
        write_json('mlflow-run.json', metadata)
        return metadata
    raise ValueError(STAGE)


def compute():
    return mlflow_training()

if __name__ == '__main__':
    run_stage()
